\(\begin{aligned}
F(\psi) &= \sqrt{\frac{2\lambda}{\pi}}\int\limits_{-\infty}^{+\infty}\mathrm{e}^{-\lambda x^2}\left[-\alpha\mathrm{e}^{-\lambda x^2} - \frac{\hbar}{4m_\mathrm{e}}\left(-2\lambda e^{-\lambda x^2} + 4\lambda^2x^2\mathrm{e}^{-\lambda x^2}\right) + \frac{e^2B_z^2x^2}{m_\mathrm{e}}\mathrm{e}^{-\lambda x^2}\right]\mathrm{d}x \\
&= \sqrt{\frac{2\lambda}{\pi}}\int\limits_{-\infty}^{+\infty}\left[\left(-\alpha + \frac{\hbar^2\lambda}{2m_\mathrm{e}}\right)\mathrm{e}^{-2\lambda x^2} + \left(\frac{e^2B_z^2}{m_e} - \frac{\hbar^2\lambda^2}{m_e}\right)x^2\mathrm{e}^{-2\lambda x^2}\right]\mathrm{d}x \\
&= -\alpha + \frac{\hbar^2\lambda}{2m_\mathrm{e}} + \left(\frac{e^2B_z^2}{m_\mathrm{e}} - \frac{\hbar^2\lambda^2}{m_\mathrm{e}}\right)\cdot\frac{1}{4\lambda} \\
&= -\alpha + \frac{\hbar^2\lambda}{4m_\mathrm{e}} + \frac{e^2B_z^2}{4\lambda m_\mathrm{e}}
\end{aligned}\)
